-- ============================================================
-- FILE: 06_import_ev_dataset.sql
-- PROJECT: EV Charging Station Network Orchestrator
-- DESCRIPTION: Imports all 15,027 predefined records from
--              the 7 CSV files into their respective tables,
--              resets PostgreSQL sequences, and inserts
--              clearly-labelled test records for the 9 operational tables.
-- Run AFTER: 05_normalization_views.sql
-- ============================================================

BEGIN;

-- Ensure status check constraint allows 'Operational', 'Inactive', 'Under Maintenance'
ALTER TABLE stations DROP CONSTRAINT IF EXISTS stations_status_check;
ALTER TABLE stations ADD CONSTRAINT stations_status_check
    CHECK (status IS NULL OR status IN ('ACTIVE', 'INACTIVE', 'UNDER_MAINTENANCE', 'OPERATIONAL', 'Active', 'Inactive', 'Under Maintenance', 'Operational'));


-- ============================================================
-- 1. STATES (1 record from state.csv)
-- ============================================================
ON CONFLICT (state_id) DO NOTHING;

-- ============================================================
-- 2. CHARGING NETWORKS (30 records from charging_network.csv)
-- ============================================================
ON CONFLICT (network_id) DO NOTHING;

-- ============================================================
-- 3. VEHICLE CATEGORIES (5 records from vehicle_category.csv)
-- ============================================================
ON CONFLICT (category_id) DO NOTHING;

-- ============================================================
-- 4. CONNECTOR TYPES (7 records from connector_type.csv)
-- ============================================================
ON CONFLICT (connector_type_id) DO NOTHING;

-- ============================================================
-- 5. TOWNS (415 records from town.csv)
-- ============================================================
ON CONFLICT (town_id) DO NOTHING;

ON CONFLICT (town_id) DO NOTHING;

ON CONFLICT (town_id) DO NOTHING;

-- ============================================================
-- 6. STATIONS (6,068 records from station_insert.sql)
-- ============================================================
ON CONFLICT (station_id) DO NOTHING;

ON CONFLICT (station_id) DO NOTHING;

ON CONFLICT (station_id) DO NOTHING;

ON CONFLICT (station_id) DO NOTHING;

ON CONFLICT (station_id) DO NOTHING;

ON CONFLICT (station_id) DO NOTHING;

ON CONFLICT (station_id) DO NOTHING;

ON CONFLICT (station_id) DO NOTHING;

ON CONFLICT (station_id) DO NOTHING;

ON CONFLICT (station_id) DO NOTHING;

ON CONFLICT (station_id) DO NOTHING;

ON CONFLICT (station_id) DO NOTHING;

ON CONFLICT (station_id) DO NOTHING;

-- ============================================================
-- 7. CHARGERS (8,501 records from charger.csv)
-- ============================================================
ON CONFLICT (charger_id) DO NOTHING;

ON CONFLICT (charger_id) DO NOTHING;

ON CONFLICT (charger_id) DO NOTHING;

ON CONFLICT (charger_id) DO NOTHING;

ON CONFLICT (charger_id) DO NOTHING;

ON CONFLICT (charger_id) DO NOTHING;

ON CONFLICT (charger_id) DO NOTHING;

ON CONFLICT (charger_id) DO NOTHING;

ON CONFLICT (charger_id) DO NOTHING;

ON CONFLICT (charger_id) DO NOTHING;

ON CONFLICT (charger_id) DO NOTHING;

ON CONFLICT (charger_id) DO NOTHING;

ON CONFLICT (charger_id) DO NOTHING;

ON CONFLICT (charger_id) DO NOTHING;

ON CONFLICT (charger_id) DO NOTHING;

ON CONFLICT (charger_id) DO NOTHING;

ON CONFLICT (charger_id) DO NOTHING;

ON CONFLICT (charger_id) DO NOTHING;

-- ============================================================
-- RESET PRIMARY KEY SEQUENCES
-- ============================================================
SELECT setval('states_state_id_seq', (SELECT COALESCE(MAX(state_id), 1) FROM states));
SELECT setval('towns_town_id_seq', (SELECT COALESCE(MAX(town_id), 1) FROM towns));
SELECT setval('charging_networks_network_id_seq', (SELECT COALESCE(MAX(network_id), 1) FROM charging_networks));
SELECT setval('vehicle_categories_category_id_seq', (SELECT COALESCE(MAX(category_id), 1) FROM vehicle_categories));
SELECT setval('connector_types_connector_type_id_seq', (SELECT COALESCE(MAX(connector_type_id), 1) FROM connector_types));
SELECT setval('stations_station_id_seq', (SELECT COALESCE(MAX(station_id), 1) FROM stations));
SELECT setval('chargers_charger_id_seq', (SELECT COALESCE(MAX(charger_id), 1) FROM chargers));

-- ============================================================
-- 8. TEST RECORDS FOR OPERATIONAL TABLES (Clearly Labelled)
-- Required to demonstrate relationships and test transaction logic
-- ============================================================

-- 8.1 USERS
ON CONFLICT (user_id) DO NOTHING;

SELECT setval('users_user_id_seq', (SELECT COALESCE(MAX(user_id), 1) FROM users));

-- 8.2 OPERATORS (1:1 with station, 1:0..1 with user)
ON CONFLICT (user_id) DO NOTHING;

-- 8.3 VEHICLES
ON CONFLICT (vehicle_id) DO NOTHING;

SELECT setval('vehicles_vehicle_id_seq', (SELECT COALESCE(MAX(vehicle_id), 1) FROM vehicles));

-- 8.4 VEHICLE_CONNECTOR_COMPATIBILITY (M:N)
ON CONFLICT DO NOTHING;

-- 8.5 RESERVATIONS
ON CONFLICT (reservation_id) DO NOTHING;

SELECT setval('reservations_reservation_id_seq', (SELECT COALESCE(MAX(reservation_id), 1) FROM reservations));

-- 8.6 CHARGING_SESSIONS
ON CONFLICT (session_id) DO NOTHING;

SELECT setval('charging_sessions_session_id_seq', (SELECT COALESCE(MAX(session_id), 1) FROM charging_sessions));

-- 8.7 PAYMENTS (amount is snapshot = energy * tariff)
ON CONFLICT (payment_id) DO NOTHING;

SELECT setval('payments_payment_id_seq', (SELECT COALESCE(MAX(payment_id), 1) FROM payments));

-- 8.8 WAITING_QUEUE_ENTRIES
ON CONFLICT (queue_id) DO NOTHING;

SELECT setval('waiting_queue_entries_queue_id_seq', (SELECT COALESCE(MAX(queue_id), 1) FROM waiting_queue_entries));

-- 8.9 NOTIFICATIONS
ON CONFLICT (notification_id) DO NOTHING;

SELECT setval('notifications_notification_id_seq', (SELECT COALESCE(MAX(notification_id), 1) FROM notifications));

COMMIT;

-- ============================================================
-- 9. IMPORT VERIFICATION QUERIES
-- Run to confirm record counts after import
-- ============================================================
SELECT 'states'                         AS table_name, COUNT(*) AS record_count FROM states
UNION ALL SELECT 'towns',                              COUNT(*) FROM towns
UNION ALL SELECT 'charging_networks',                  COUNT(*) FROM charging_networks
UNION ALL SELECT 'vehicle_categories',                  COUNT(*) FROM vehicle_categories
UNION ALL SELECT 'connector_types',                    COUNT(*) FROM connector_types
UNION ALL SELECT 'stations',                           COUNT(*) FROM stations
UNION ALL SELECT 'chargers',                           COUNT(*) FROM chargers
UNION ALL SELECT 'users',                              COUNT(*) FROM users
UNION ALL SELECT 'operators',                          COUNT(*) FROM operators
UNION ALL SELECT 'vehicles',                           COUNT(*) FROM vehicles
UNION ALL SELECT 'vehicle_connector_compatibility',   COUNT(*) FROM vehicle_connector_compatibility
UNION ALL SELECT 'reservations',                       COUNT(*) FROM reservations
UNION ALL SELECT 'charging_sessions',                  COUNT(*) FROM charging_sessions
UNION ALL SELECT 'payments',                           COUNT(*) FROM payments
UNION ALL SELECT 'waiting_queue_entries',               COUNT(*) FROM waiting_queue_entries
UNION ALL SELECT 'notifications',                      COUNT(*) FROM notifications
ORDER BY table_name;
